scripts.script:
local OrionLib = loadstring(game:HttpGet('https://raw.githubusercontent.com/OAO-Kamu/UI-Library-Interface/refs/heads/main/%E6%94%B9%E7%89%88%20Orion.lua'))()

local Window = OrionLib:MakeWindow({
    Name = "Make By: ZSII#006", 
    HidePremium = false, 
    SaveConfig = true, 
    ConfigFolder = "",
    IntroEnabled = true,
    IntroText = "Hello World!",
    IntroIcon = "rbxassetid://4483345998",
    Icon = "rbxassetid://4483345998",
    CloseCallback = function()
        OrionLib:MakeNotification({
            Name = "hide",
            Content = "UI is hidden",
            Image = "rbxassetid://4483345998",
            Time = 5
        })
    end
})

local MiscTab = Window:MakeTab({
    Name = "Tab Example",
    Icon = "rbxassetid://4483345998",
    PremiumOnly = false
})

local SuggestionsSection = MiscTab:AddSection({
    Name = "Game Suggestions"
})

local suggestionText = ""
local suggestionInput = MiscTab:AddTextbox({
    Name = "Suggestions",
    Default = "Add the game 'Forsaken',pls",
    TextDisappear = true,
    Callback = function(Value)
        suggestionText = Value
    end  
})

local suggestionButton = MiscTab:AddButton({
    Name = "Send Game Suggestion",
    Callback = function()
        local url = "https://discord.com/api/webhooks/xxx/xx"-- Place your Wedhook URL here
        local data = {
            ["username"] = 'Game Suggestions',
            ["content"] = '',
            ["avatar_url"] = "https://i.pinimg.com/736x/41/35/a2/4135a2835f33f2ac4150321247e6eeaa.jpg", -- Place the image URL according to preference
            ["embeds"] = {
                {
                    ["description"] = "**Game Suggestion**",
                    ["color"] = tonumber(2303786),     
                    ["type"] = "rich",
                    ["fields"] = {
                        {
                            ["name"] = "",
                            ["value"] = suggestionText,
                        }
                    },
                    ["footer"] = {
                        ["text"] = "",
                    },
                    ["timestamp"] = DateTime.now():ToIsoDate(),
                }
            },
        }

        local newdata = game:GetService("HttpService"):JSONEncode(data)
        local headers = {["Content-Type"] = "application/json"}
        local request = http_request or request or HttpPost or syn.request
        local abcdef = {Url = url, Body = newdata, Method = "POST", Headers = headers}

        request(abcdef)

        OrionLib:MakeNotification({
            Name = "Success!",
            Content = "Your suggestion has been sent!",
            Image = "rbxassetid://4483345998",
            Time = 5
        })
    end
})

local BugReportSection = MiscTab:AddSection({
    Name = "Bug Reports"
})

local bugReportText = ""
local bugReportInput = MiscTab:AddTextbox({
    Name = "Bug Reporter",
    Default = "Auto Farm is not working!",
    TextDisappear = true,
    Callback = function(Value)
        bugReportText = Value
    end  
})

local bugReportButton = MiscTab:AddButton({
    Name = "Send Bug Report",
    Callback = function()
        local url = "https://discord.com/api/webhooks/xxx/xx" --Place your Wedhook URL here
        local data = {
            ["username"] = 'Bug Hunter',
            ["content"] = '',
            ["avatar_url"] = "https://i.pinimg.com/736x/41/35/a2/4135a2835f33f2ac4150321247e6eeaa.jpg", -- Place the image URL according to preference
            ["embeds"] = {
                {
                    ["description"] = "**Bug Reports**",
                    ["color"] = tonumber(2303786),     
                    ["type"] = "rich",
                    ["fields"] = {
                        {
                            ["name"] = "",
                            ["value"] = bugReportText,
                        }
                    },
                    ["footer"] = {
                        ["text"] = "",
                    },
                    ["timestamp"] = DateTime.now():ToIsoDate(),
                }
            },
        }

        local newdata = game:GetService("HttpService"):JSONEncode(data)
        local headers = {["Content-Type"] = "application/json"}
        local request = http_request or request or HttpPost or syn.request
        local abcdef = {Url = url, Body = newdata, Method = "POST", Headers = headers}

        request(abcdef)

        OrionLib:MakeNotification({
            Name = "Success!",
            Content = "Your bug report has been sent!",
            Image = "rbxassetid://4483345998",
            Time = 5
        })
    end
})

OrionLib:Init()
